import React, { useState } from 'react';
import { useNavigate, useLocation } from 'react-router-dom';
import './Navigation.css';

const Navigation = () => {
  const navigate = useNavigate();
  const location = useLocation();
  const [isMobileMenuOpen, setIsMobileMenuOpen] = useState(false);

  const navItems = [
    { path: '/profile', label: 'Profile', icon: '👤' },
    { path: '/employee-dashboard', label: 'Dashboard', icon: '📊' },
    { path: '/manager-dashboard', label: 'Manager', icon: '👨‍💼' },
    { path: '/debug', label: 'Debug', icon: '🐛' },
  ];

  const handleLogout = () => {
    localStorage.removeItem('token');
    navigate('/login');
  };

  const toggleMobileMenu = () => {
    setIsMobileMenuOpen(!isMobileMenuOpen);
  };

  return (
    <nav className="nav-main">
      <div className="nav-container">
        {/* Logo/Brand */}
        <div className="nav-brand" onClick={() => navigate('/')}>
          <div className="nav-logo">
            <span className="nav-logo-icon">🚀</span>
            <span className="nav-logo-text">PRixGEn</span>
          </div>
        </div>

        {/* Desktop Navigation */}
        <div className="nav-desktop">
          <div className="nav-links">
            {navItems.map((item) => (
              <button
                key={item.path}
                className={`nav-link ${location.pathname === item.path ? 'nav-link-active' : ''}`}
                onClick={() => navigate(item.path)}
              >
                <span className="nav-link-icon">{item.icon}</span>
                <span className="nav-link-label">{item.label}</span>
              </button>
            ))}
          </div>
          
          <button className="btn btn-secondary nav-logout" onClick={handleLogout}>
            <span className="nav-logout-icon">🚪</span>
            <span className="nav-logout-text">Logout</span>
          </button>
        </div>

        {/* Mobile Menu Button */}
        <button 
          className="nav-mobile-toggle"
          onClick={toggleMobileMenu}
          aria-label="Toggle mobile menu"
        >
          <span className={`hamburger ${isMobileMenuOpen ? 'open' : ''}`}></span>
        </button>
      </div>

      {/* Mobile Navigation */}
      <div className={`nav-mobile ${isMobileMenuOpen ? 'nav-mobile-open' : ''}`}>
        <div className="nav-mobile-links">
          {navItems.map((item) => (
            <button
              key={item.path}
              className={`nav-mobile-link ${location.pathname === item.path ? 'nav-mobile-link-active' : ''}`}
              onClick={() => {
                navigate(item.path);
                setIsMobileMenuOpen(false);
              }}
            >
              <span className="nav-mobile-link-icon">{item.icon}</span>
              <span className="nav-mobile-link-label">{item.label}</span>
            </button>
          ))}
          <button className="nav-mobile-logout" onClick={handleLogout}>
            <span className="nav-mobile-logout-icon">🚪</span>
            <span className="nav-mobile-logout-text">Logout</span>
          </button>
        </div>
      </div>
    </nav>
  );
};

export default Navigation;
